"""Control Center feature; runtime dependencies are supplied by the composition root."""
from __future__ import annotations
from typing import Any

def f(services, name: str, label: str, kind: str = "text", **extra: Any) -> dict[str, Any]:
    value = {"name": name, "label": label, "type": kind}
    value.update(extra)
    return value

def action(services, 
    action_id: str,
    title: str,
    group: str,
    description: str,
    command: str,
    fields: list[dict[str, Any]] | None = None,
    *,
    danger: bool = False,
    stdin_fields: list[str] | None = None,
    secret_profile: str | None = None,
    secret_mode: str = "secret-edit",
    external_url: str | None = None,
) -> dict[str, Any]:
    value = {
        "id": action_id,
        "title": title,
        "group": group,
        "description": description,
        "command": command,
        "fields": fields or [],
        "danger": danger,
        "stdinFields": stdin_fields or [],
    }
    if secret_profile:
        value["kind"] = secret_mode
        value["profile"] = secret_profile
    if external_url:
        value["externalUrl"] = external_url
    return value

